pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 amount) public {
        // Keep amount within the range of a realistic ETH balance
        bound(amount, 0, 100 ether);
        // Ensure caller has enough ETH to send
        address msgSender = address(this);
        vm.deal(msgSender, amount);
        uint256 balanceBefore = address(c).balance;
        // The reference contract requires amount == 1 ether, so only that amount succeeds;
        // the buggy version accepts any amount that the caller has.
        // For the reference, the call will revert when amount != 1 ether, the balance delta will be 0.
        // For the buggy version, the call succeeds with any amount, changing the balance.
        vm.prank(msgSender);
        try c.lockInGuess{value: amount}(hash) {
            // call succeeded
        } catch {
            // call reverted
        }
        uint256 balanceAfter = address(c).balance;
        // The invariant: the contract balance increase must be either 0 (if the call reverted)
        // or exactly 1 ether (if the call succeeded). The buggy version violates this by
        // allowing a positive delta that is != 1 ether.
        uint256 delta = balanceAfter - balanceBefore;
        assertTrue(delta == 0 || delta == 1 ether);
    }
}

