pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 amount, address caller) public {
        vm.assume(amount <= 100 ether);
        vm.assume(caller != address(0));
        vm.deal(caller, amount);
        vm.prank(caller);
        try c.lockInGuess{value: amount}(hash) {
            // If the call succeeds, the reference must have required exactly 1 ether payment.
            // Thus the caller's balance after the call must have decreased by exactly 1 ether.
            // The buggy version allows success with any amount, so this check will fail for amount != 1 ether.
            assertTrue(amount == 1 ether, "Reference requires exactly 1 ether");
        } catch {
            // If the call reverts, the reference must have rejected the call.
            // For the reference, reverts happen if amount != 1 ether or if the caller already has a guess.
            // The buggy version only reverts if the caller already has a guess.
            // So we assert that amount != 1 ether OR the caller already had a guess.
            // But we can't easily check the pre-state without reading internal mapping, so we skip asserting in catch.
            // Instead, we rely on the success path to catch the bug.
        }
    }
}

