pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 lockInCount;

    function setUp() public {
        c = new C{value: 1 ether}();
        lockInCount = 0;
    }

    function testFuzz_property(bytes32 hash, uint256 msgValue) public {
        // Restrict msgValue to admissible range: 0 to 1 ether (wide enough to include 0 and 1)
        vm.assume(msgValue <= 1 ether);

        // Fuzzed caller with sufficient balance
        address caller = address(0xbeef);
        vm.deal(caller, 1 ether);

        // Prank as caller and call lockInGuess with fuzzed value
        vm.prank(caller);
        try c.lockInGuess{value: msgValue}(hash) {
            lockInCount++;
        } catch {
            // If it reverts, balance should remain at current lockInCount * 1 ether
        }

        // General invariant: c.balance must equal lockInCount * 1 ether
        assertEq(address(c).balance, lockInCount * 1 ether);
    }
}

