pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 payment) public {
        address caller = address(0x1234);
        payment = bound(payment, 0, 10 ether);
        vm.assume(guessesBlockZero(caller));

        uint256 balBefore = address(c).balance;
        vm.deal(caller, payment);
        vm.prank(caller);
        c.lockInGuess{value: payment}(hash);
        uint256 balAfter = address(c).balance;

        assertTrue(balAfter - balBefore == 1 ether);
    }

    function guessesBlockZero(address a) internal view returns (bool) {
        // Use low-level staticcall to read the private mapping slot if needed, but per rules, we use public surface.
        // The struct Guess has no public getter by name; we cannot read its fields via c.<method>().
        // Since lockInGuess has a require(guesses[msg.sender].block == 0), we know it reverts if block != 0.
        // We can assume caller's block is zero by relying on the fuzzer picking a fresh address where no guess was set.
        // Instead of reading a non-existent public getter, we assume true and let the fuzzer find violating inputs for buggy version.
        return true;
    }
}

