pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, uint8 delay) public {
        vm.assume(delay >= 1);
        address player = address(0x1234);
        vm.deal(player, 1 ether);
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(guessHash);
        vm.roll(block.number + delay + 2);
        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number - delay - 1)));
        bool origSettleOk;
        try c.settle() {
            origSettleOk = true;
        } catch {
            origSettleOk = false;
        }
        // Recreate contract for mutant scenario (here we use the same C, but mutant is deployed separately in practice)
        // In this test, we test the invariant on the reference; the fuzzer will find the case where reference settle succeeds and mutant reverts.
        // However, the test code can only assert on the reference; the violation will be observed when running against the mutant.
        // The invariant: if settle() succeeds, it must have been called after lock block + 1.
        bool referenceSettleOk;
        try c.settle() {
            referenceSettleOk = true;
        } catch {
            referenceSettleOk = false;
        }
        // We need a property that holds on reference but fails on mutant.
        // For the reference, settle succeeds iff block.number > block + 1 (where block = block at lock + 1).
        // Since we locked at block L, reference stores L+1, so needs block.number > L+1 => current > L+1.
        // Mutant stores L+2, needs current > L+2.
        // If we set current = L+2, reference succeeds, mutant reverts.
        // So the invariant: if block.number == lockBlock + 2, settle() must succeed. Reference holds it, mutant breaks it.
        // We can encode this as: after locking at block L, advancing to L+2, settle() should succeed.
        // But we must avoid hardcoding L; we can compute it from guesses getter.
        // The getter is not auto-generated for mappings with struct values, but we can observe via settle revert or balance change.
        // Actually, settle modifies balance, so we can check balance before/after.
        // Simpler: assert that when current block is exactly two more than the block when lockInGuess was called, settle succeeds.
        // We can compute lock block via a getter? No public getter for mapping of struct. So we use event? No.
        // Alternative: we observe that reference always allows settle at lockBlock+2, while mutant requires lockBlock+3.
        // We can test by calling settle after a fixed advance and checking it doesn't revert.
        // So we need to assert on the revert outcome.
        // We'll compute the block number right after lockInGuess (lockBlock = block.number - 1 after the call).
        // Then we roll to lockBlock + 2 and assert settle succeeds on reference.
        // But we cannot read guesses[player].block from outside. However, we know the lock block is the block.number during lockInGuess.
        // We can capture block.number immediately after lockInGuess returns.
        uint256 lockCallBlock = block.number; // This is the block of the lockInGuess transaction.
        // Reference stores lockCallBlock + 1, mutant stores lockCallBlock + 2.
        // For the reference, settle needs > lockCallBlock + 1 => >= lockCallBlock + 2.
        // So at lockCallBlock + 2, settle succeeds on reference.
        // For mutant, settle needs > lockCallBlock + 2 => >= lockCallBlock + 3.
        // So at lockCallBlock + 2, mutant settle reverts.
        vm.roll(lockCallBlock + 2);
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
        // The invariant: settle must succeed at lockCallBlock + 2.
        // Reference holds, mutant breaks.
        assertTrue(ok);
    }
}

