pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint8 blockOffset) public {
        // Restrict blockOffset to keep the test within admissible domain and avoid overflow
        blockOffset = uint8(bound(blockOffset, 1, 10));
        address caller = address(0x1234);
        vm.deal(caller, 1 ether);
        vm.deal(address(c), 0);

        // Set block to a fixed number to have a known base
        vm.roll(100);
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(hash);

        // Advance to block 100 + blockOffset. At blockOffset=2 the mutant should fail.
        vm.roll(100 + blockOffset);

        bool settleOk;
        vm.prank(caller);
        try c.settle() { settleOk = true; } catch { settleOk = false; }

        // The reference C settles correctly for any blockOffset >= 2 (since lock is at 101, settle requires >101).
        // For the mutant, lock is at 102, settle requires >102, so at block 102 it reverts.
        // Thus, assert that when blockOffset == 2 (i.e., block=102), settle must always succeed.
        // The test asserts that the property holds for ALL blockOffsets, which the reference satisfies
        // and the mutant breaks for blockOffset=2.
        assertTrue(settleOk);
    }
}

