pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 fuzzBalance) public {
        // Keep balance in admissible range: at least 2 ether for a potential settle payout
        fuzzBalance = bound(fuzzBalance, 2 ether, 100 ether);
        vm.deal(address(this), fuzzBalance);
        // Ensure the contract has balance; we transfer directly to mimic correct setup
        vm.deal(address(c), 2 ether);

        // Fund and call lockInGuess with the fuzzed value (exactly 1 ether required)
        vm.deal(address(this), 2 ether);
        vm.prank(address(this));
        try c.lockInGuess{value: 1 ether}(hash) {
            // success path
        } catch {
            // failure allowed; we check final balance
        }

        // General rule: if lockInGuess succeeded, contract balance must be at least 2 ether (2 from initial, 1 from lock).
        // The mutant with msg.value == 0 ether would allow locking without sending ether, leaving balance at 2 ether.
        // Actually both would have 2 ether? Wait: reference needs msg.value == 1 ether, so call with 1 ether is valid.
        // Mutant requires 0 ether, so call with 1 ether fails. So different behavior.
        // But we need an assertion that holds for reference and fails for mutant.
        // After any valid lockInGuess, the contract must have collected 1 more ether.
        // Reference: call with 1 ether succeeds -> balance becomes 3 ether.
        // Mutant: call with 1 ether fails -> balance stays 2 ether.
        // So assert: after attempt, if c.guesses(address this) non-zero, balance >= 3 ether.
        // Or simpler: assert balance >= 2 ether + (guesses[this].block == 0 ? 0 : 1 ether)
        (uint256 blk,) = c.guesses(address(this));
        bool locked = blk != 0;
        uint256 expectedMin = 2 ether + (locked ? 1 ether : 0);
        assertTrue(address(c).balance >= expectedMin);
    }
}

