pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 blockOffset) public {
        // Restrict to admissible domain: non-zero hash and blockOffset >= 1
        vm.assume(hash != bytes32(0));
        vm.assume(blockOffset >= 1 && blockOffset <= 256);

        // Setup actor with enough ether for lockInGuess
        address actor = address(0x1000);
        vm.deal(actor, 10 ether);

        // Fund the contract with initial ether (constructor requires 1 ether)
        vm.deal(address(c), 10 ether);

        // Actor locks in a non-zero hash
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // Warp to a block where the blockhash will resolve
        uint256 targetBlock = block.number + blockOffset;
        vm.roll(targetBlock);
        vm.warp(block.timestamp + blockOffset * 12);

        // If the hash matches the blockhash of the locked block, reference pays 2 ether, mutant stores 0 and may not
        bytes32 resolvedBlockhash = blockhash(targetBlock - blockOffset + 1);
        bool shouldMatch = (hash == resolvedBlockhash);

        // Record balance before settle
        uint256 balanceBefore = actor.balance;

        // Actor tries to settle
        vm.prank(actor);
        try c.settle() {
            // Check if payout occurred
            uint256 balanceAfter = actor.balance;
            if (shouldMatch) {
                // Reference must pay out 2 ether when hash matches
                assertTrue(balanceAfter == balanceBefore + 2 ether);
            }
        } catch {
            // If settle reverts, it must not be a case where hash matches in reference
            // The mutant may revert when it shouldn't, or fail to pay
            if (shouldMatch) {
                // settle should not revert if the hash matches
                // This assertion will fail on the mutant when shouldMatch is true and the mutant's zero guess doesn't match
                assertTrue(false);
            }
