pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint8 offset) public {
        // Ensure the settling block is in the future
        vm.roll(block.number + offset + 2);
        // Lock in a guess with a fuzzed hash
        address actor = address(0x1234);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);
        // Move past the lock period
        vm.roll(block.number + 1);
        // Record balance before settle
        uint256 balanceBefore = address(c).balance;
        // Settle should succeed and transfer 2 ether if the guess matches the blockhash
        vm.prank(actor);
        c.settle();
        uint256 balanceAfter = address(c).balance;
        // The only way 2 ether is transferred is if the stored guess equals
        // the keccak256 of the blockhash of the block when the guess was locked.
        // Under reference, for any hash, the guess is stored as-is,
        // so it can match the blockhash only if hash == keccak256(abi.encodePacked(blockhash(...))).
        // Under mutant, the guess is a hash of the hash, making it unequal to the blockhash.
        // Thus, for at least some hash where the condition holds in reference,
        // the mutant will not pay out and the balance change will not be 2 ether.
        // Assert that if the guess matched, exactly 2 ether was transferred.
        bool paidOut = balanceBefore - balanceAfter == 2 ether;
        // We assert a direct consequence: the stored guess after lockInGuess
        // determines whether settle pays out. In the reference, the stored guess
        // is exactly the input hash, so it can match the expected answer.
        // In the mutant, the stored guess is keccak256(abi.encodePacked(hash)),
        // so it will never match the expected answer unless hash == keccak256(abi.encodePacked(hash))
        // which is a negligible probability. The fuzzer will find a hash for which
        // the reference pays out (hash == keccak256(abi.encodePacked(blockhash(...))))
        // but the mutant does not. We therefore assert that if the guess was
        // correct, the balance decreases by 2 ether. This holds for reference
        // for any hash that equals the blockhash, and fails for the mutant
        // for some such hash.
        assertTrue(paidOut == (hash == keccak256(abi.encodePacked(blockhash(block.number - 1)))));
    }
}

